  QuizQuestion(id:'q20',category:'Kur’an',question:'Kur’an’da adı geçen Roma anlamındaki sure hangisidir?',options:['Rûm','Sebe','Fâtır','Şûrâ'],answer:0,explanation:'Rûm suresi 30. suredir.',source:'Rûm Suresi'),
  QuizQuestion(id:'q21',category:'Kur’an',question:'Kur’an’da Hz. Musa ile birlikte adı sıkça geçen kardeşi kimdir?',options:['İsmail','Harun','Yusuf','İlyas'],answer:1,explanation:'Harun, Musa’nın kardeşi ve yardımcısı olarak anılır.',source:'Tâhâ 20:29-36'),
  QuizQuestion(id:'q22',category:'Kur’an',question:'Zülkarneyn kıssası hangi surede yer alır?',options:['Kehf','Yâsîn','Mülk','Vâkıa'],answer:0,explanation:'Zülkarneyn kıssası Kehf suresindedir.',source:'Kehf 18:83-98'),
  QuizQuestion(id:'q23',category:'Kur’an',question:'Ashâb-ı Kehf kıssası hangi surede anlatılır?',options:['Kehf','Enbiyâ','Sâd','Fetih'],answer:0,explanation:'Kıssa Kehf suresinin ilgili bölümündedir.',source:'Kehf 18:9-26'),
  QuizQuestion(id:'q24',category:'Kur’an',question:'Hz. Yunus’un balık tarafından yutulması hangi surede açıkça anılır?',options:['Sâffât','Fîl','Kâria','Tekâsür'],answer:0,explanation:'Sâffât suresinde Yunus kıssası anlatılır.',source:'Sâffât 37:139-148'),
  QuizQuestion(id:'q25',category:'Kur’an',question:'Kur’an’da “iki denizin birleştiği yer” kıssasında Hz. Musa kiminle yolculuk eder?',options:['Hızır olarak bilinen kul','Hz. İbrahim','Hz. Davud','Hz. İsa'],answer:0,explanation:'Kehf suresindeki kıssada Musa, Allah’ın özel bilgi verdiği bir kul ile buluşur.',source:'Kehf 18:60-82'),

  // 20 Hadith questions: references use collection/book or well-known hadith wording.
  QuizQuestion(id:'h01',category:'Hadis',question:'“Ameller niyetlere göredir” hadisi hangi konunun önemini vurgular?',options:['Niyet','Ticaret','Yolculuk','Miras'],answer:0,explanation:'Amelin değerlendirilmesinde niyetin önemini bildirir.',source:'Sahih al-Buhari, Bed’ü’l-vahy; Sahih Muslim, İmâre'),
  QuizQuestion(id:'h02',category:'Hadis',question:'“Müslüman, elinden ve dilinden Müslümanların emin olduğu kimsedir” hadisi neyi vurgular?',options:['Güven ve zarar vermemeyi','Çok konuşmayı','Yalnız yaşamayı','Ticaret yapmayı'],answer:0,explanation:'Başkalarına söz ve davranışla zarar vermemek esastır.',source:'Sahih al-Buhari, Îmân; Sahih Muslim, Îmân'),
  QuizQuestion(id:'h03',category:'Hadis',question:'“Kolaylaştırın, zorlaştırmayın” hadisi hangi yaklaşımı öğütler?',options:['Kolaylaştırmayı','İnsanları uzaklaştırmayı','Aşırılığı','Sessiz kalmayı'],answer:0,explanation:'Dinde insanlara kolaylık gösterilmesi öğütlenir.',source:'Sahih al-Buhari, İlim; Sahih Muslim, Cihâd ve siyer'),
  QuizQuestion(id:'h04',category:'Hadis',question:'“Temizlik imanın yarısıdır” ifadesi hangi kaynakta yer alır?',options:['Sahih Muslim','Sahih al-Buhari','Muvatta dışında hiçbir kaynakta yok','Tirmizî dışında hiçbir kaynakta yok'],answer:0,explanation:'Rivayet Sahih Muslim’de yer alır.',source:'Sahih Muslim, Tahâret'),
  QuizQuestion(id:'h05',category:'Hadis',question:'“Komşusu açken tok yatan bizden değildir” sözü hangi değere dikkat çeker?',options:['Komşuyu gözetmeye','Yolculuğa','Ticarete','Savaşa'],answer:0,explanation:'Komşunun ihtiyacını gözetmek teşvik edilir.',source:'el-Müstedrek li’l-Hâkim; rivayetin sıhhati hakkında değerlendirmeler vardır'),
  QuizQuestion(id:'h06',category:'Hadis',question:'“Kişi sevdiğiyle beraberdir” hadisi hangi eserde rivayet edilmiştir?',options:['Buhari ve Müslim','Yalnız İbn Mâce','Yalnız Nesâî','Hiçbir hadis kitabında'],answer:0,explanation:'Enes b. Mâlik rivayeti iki Sahih’te de yer alır.',source:'Sahih al-Buhari, Edeb; Sahih Muslim, Birr'),
  QuizQuestion(id:'h07',category:'Hadis',question:'“Din nasihattir” hadisine göre dinin temel öğelerinden biri nedir?',options:['Samimi öğüt ve bağlılık','Mal biriktirmek','Şöhret kazanmak','Sürekli tartışmak'],answer:0,explanation:'Hadis, Allah’a, kitabına, elçisine ve Müslümanlara karşı nasihati sayar.',source:'Sahih Muslim, Îmân'),
  QuizQuestion(id:'h08',category:'Hadis',question:'“Güçlü kimse güreşte yenen değil, öfke anında kendine hâkim olandır” hadisi neyi över?',options:['Öfkeyi kontrol etmeyi','Fiziksel gücü','Zenginliği','Hızlı konuşmayı'],answer:0,explanation:'Asıl güç, öfke anında kendini tutabilmektir.',source:'Sahih al-Buhari, Edeb; Sahih Muslim, Birr'),
  QuizQuestion(id:'h09',category:'Hadis',question:'“Sizden biri kendisi için istediğini kardeşi için de istemedikçe…” hadisi hangi ahlaki ilkeyi anlatır?',options:['Kardeşi için iyilik istemeyi','Yalnızlığı','Ticareti','Yolculuğu'],answer:0,explanation:'Hadis, müminler arasında karşılıklı iyilik ve gönül birliğini vurgular.',source:'Sahih al-Buhari, Îmân; Sahih Muslim, Îmân'),
  QuizQuestion(id:'h10',category:'Hadis',question:'“Güzel söz sadakadır” hadisi hangi davranışı teşvik eder?',options:['Güzel ve faydalı konuşmayı','Susmayı her durumda zorunlu kılmayı','Mal toplamayı','Tartışmayı'],answer:0,explanation:'İyilik içeren söz de sadaka değeri taşır.',source:'Sahih al-Buhari, Sulh; Sahih Muslim, Zekât'),
  QuizQuestion(id:'h11',category:'Hadis',question:'“Merhamet etmeyene merhamet olunmaz” hadisi hangi değeri öne çıkarır?',options:['Merhameti','Cesareti','Zenginliği','Şöhreti'],answer:0,explanation:'Merhametli davranmak teşvik edilir.',source:'Sahih al-Buhari, Edeb; Sahih Muslim, Fedâil'),
  QuizQuestion(id:'h12',category:'Hadis',question:'“Allah sizin suretlerinize ve mallarınıza değil, kalplerinize ve amellerinize bakar” hadisi neyi öne çıkarır?',options:['Kalp ve amelleri','Dış görünüşü','Serveti','Soyu'],answer:0,explanation:'Değerlendirmede kalp ve davranışların önemi belirtilir.',source:'Sahih Muslim, Birr'),
  QuizQuestion(id:'h13',category:'Hadis',question:'“Zarar vermek de zarara zararla karşılık vermek de yoktur” kaidesi hangi ilkeyle bilinir?',options:['Lâ darar ve lâ dirâr','Ameller niyetlere göredir','Din nasihattir','Kolaylaştırın'],answer:0,explanation:'Fıkıhta zarar vermeme ilkesi olarak kullanılır.',source:'İbn Mâce, Ahkâm; Muvatta, Akdiye; rivayet yolları değerlendirilir'),
  QuizQuestion(id:'h14',category:'Hadis',question:'“Allah güzeldir, güzelliği sever” hadisi hangi davranış bağlamında aktarılır?',options:['Kibir ile güzel giyinmeyi ayırırken','Oruç vakitlerini anlatırken','Miras paylaşımını anlatırken','Hac menasikini anlatırken'],answer:0,explanation:'Hadiste kibir, hakkı reddetmek ve insanları küçümsemek olarak açıklanır.',source:'Sahih Muslim, Îmân'),
  QuizQuestion(id:'h15',category:'Hadis',question:'“İlim öğrenmek her Müslümana farzdır” sözü hangi konuyla ilgilidir?',options:['İlim öğrenmenin önemi','Yalnız ticaret','Savaş hazırlığı','Yolculuk adabı'],answer:0,explanation:'İlim talebinin önemini ifade eden meşhur rivayettir; sıhhat değerlendirmesi kaynaklara göre ele alınır.',source:'İbn Mâce, Mukaddime; rivayetin isnadı hakkında ihtilaflı değerlendirmeler'),
  QuizQuestion(id:'h16',category:'Hadis',question:'“Gülümsemen kardeşine sadakadır” rivayeti hangi davranışı teşvik eder?',options:['Güler yüzlü olmayı','Mal biriktirmeyi','Sessiz kalmayı','Yolculuğu'],answer:0,explanation:'İnsanlara güler yüz göstermek iyilik sayılır.',source:'Câmiʿ et-Tirmizî, Birr; hasen değerlendirmesi'),
  QuizQuestion(id:'h17',category:'Hadis',question:'“Kim Allah’a ve ahiret gününe inanıyorsa ya hayır söylesin ya sussun” hadisi neyi öğretir?',options:['Dili korumayı','Çok konuşmayı','Tartışmayı','Şaka yapmamayı'],answer:0,explanation:'Sözün hayırlı olması veya susmanın tercih edilmesi öğütlenir.',source:'Sahih al-Buhari, Edeb; Sahih Muslim, Îmân'),
  QuizQuestion(id:'h18',category:'Hadis',question:'“Her iyilik sadakadır” hadisi hangi anlayışı destekler?',options:['İyiliğin geniş anlamda sadaka oluşunu','Sadakanın yalnız parayla yapılmasını','Yardımın sadece akrabaya yapılmasını','İyiliğin gizlenmesini'],answer:0,explanation:'Maddi olmayan iyilikler de sadaka kapsamına girebilir.',source:'Sahih al-Buhari, Edeb'),
  QuizQuestion(id:'h19',category:'Hadis',question:'“Allah’a en sevimli amel, az da olsa devamlı olanıdır” hadisi neyi tavsiye eder?',options:['Sürekliliği','Aşırı yüklenmeyi','Ara sıra ibadeti','Gösterişi'],answer:0,explanation:'Düzenli ve devamlı amel övülür.',source:'Sahih al-Buhari, Rikāk; Sahih Muslim, Salâtü’l-müsâfirîn'),
  QuizQuestion(id:'h20',category:'Hadis',question:'“Bir Müslüman bir ağaç diker veya ekin eker de ondan kuş, insan ya da hayvan yerse…” hadisi neyi bildirir?',options:['Üretip canlılara fayda sağlamanın sevabını','Ticaret yasağını','Ağaç kesmenin faziletini','Yalnızca tarım vergisini'],answer:0,explanation:'Canlıların faydalandığı ekim ve dikim sadaka olarak değerlendirilir.',source:'Sahih al-Buhari, Müzâraʿa; Sahih Muslim, Müsâkât'),

  // 25 Seerah questions
  QuizQuestion(id:'s01',category:'Siyer',question:'Hz. Muhammed (s.a.v.) hangi şehirde doğmuştur?',options:['Medine','Mekke','Taif','Kudüs'],answer:1,explanation:'Mekke’de dünyaya gelmiştir.',source:'İbn Hişâm, es-Sîre; klasik siyer kaynakları'),
  QuizQuestion(id:'s02',category:'Siyer',question:'İlk vahiy hangi mağarada gelmiştir?',options:['Sevr','Hira','Uhud','Nur'],answer:1,explanation:'İlk vahiy Hira mağarasında gelmiştir.',source:'Sahih al-Buhari, Bed’ü’l-vahy'),
  QuizQuestion(id:'s03',category:'Siyer',question:'İlk vahiy geldiğinde Hz. Muhammed’in yaşı geleneksel siyer anlatımında kaçtır?',options:['25','30','40','50'],answer:2,explanation:'İlk vahiy sırasında kırk yaşında olduğu aktarılır.',source:'İbn Hişâm, es-Sîre; Sahih al-Buhari, Bed’ü’l-vahy'),
  QuizQuestion(id:'s04',category:'Siyer',question:'Hz. Muhammed’in ilk eşi kimdir?',options:['Hz. Âişe','Hz. Hatice','Hz. Hafsa','Hz. Sevde'],answer:1,explanation:'İlk eşi Hz. Hatice’dir.',source:'İbn Hişâm, es-Sîre'),
  QuizQuestion(id:'s05',category:'Siyer',question:'İslam’ı kabul eden ilk kişi olarak geleneksel kaynaklarda kim anılır?',options:['Hz. Hatice','Hz. Ömer','Hz. Hamza','Hz. Abbas'],answer:0,explanation:'İlk vahiyden sonra Hz. Hatice iman etmiştir.',source:'İbn Hişâm, es-Sîre; Sahih al-Buhari, Bed’ü’l-vahy'),
  QuizQuestion(id:'s06',category:'Siyer',question:'Hicret sırasında Hz. Muhammed’e yol arkadaşlığı yapan sahabi kimdir?',options:['Hz. Ali','Hz. Ebû Bekir','Hz. Osman','Hz. Bilâl'],answer:1,explanation:'Hicret yolculuğunda Hz. Ebû Bekir ona eşlik etmiştir.',source:'Tevbe 9:40; Sahih al-Buhari, Menâkıbü’l-Ensâr'),
  QuizQuestion(id:'s07',category:'Siyer',question:'Hicret yolculuğunda saklanılan mağaranın adı nedir?',options:['Hira','Sevr','Uhud','Nur'],answer:1,explanation:'Mekke’den ayrılırken Sevr mağarasında kalmışlardır.',source:'Tevbe 9:40; siyer kaynakları'),
  QuizQuestion(id:'s08',category:'Siyer',question:'Hicretin varış şehri olan Yesrib daha sonra hangi adla tanınmıştır?',options:['Kûfe','Medine','Şam','Basra'],answer:1,explanation:'Yesrib, Medinetü’n-Nebi adıyla anılmıştır.',source:'Siyer kaynakları; Medine dönemi'),
  QuizQuestion(id:'s09',category:'Siyer',question:'Hz. Muhammed’in Medine’de inşa ettirdiği ilk mescit hangisidir?',options:['Mescid-i Nebevî','Kuba Mescidi','Mescid-i Aksâ','Kıbleteyn'],answer:1,explanation:'Kuba Mescidi hicret yolunda inşa edilmiştir.',source:'Siyer kaynakları; Tevbe 9:108 ile ilişkilendirilir'),
  QuizQuestion(id:'s10',category:'Siyer',question:'Müslümanların ilk kıblesi hangi şehirdedir?',options:['Mekke','Kudüs','Medine','Taif'],answer:1,explanation:'İlk kıble Kudüs yönündeydi.',source:'Bakara 2:142-150; hadis ve siyer kaynakları'),
  QuizQuestion(id:'s11',category:'Siyer',question:'Bedir Savaşı hangi hicrî yılda gerçekleşmiştir?',options:['1','2','3','5'],answer:1,explanation:'Bedir Gazvesi hicretin ikinci yılında gerçekleşmiştir.',source:'Siyer ve megāzî kaynakları'),
  QuizQuestion(id:'s12',category:'Siyer',question:'Uhud Savaşı hangi hicrî yılda gerçekleşmiştir?',options:['2','3','5','8'],answer:1,explanation:'Uhud Gazvesi hicretin üçüncü yılında gerçekleşmiştir.',source:'Âl-i İmrân 3:121-180; siyer kaynakları'),
  QuizQuestion(id:'s13',category:'Siyer',question:'Hendek (Ahzâb) Savaşı hangi hicrî yılda gerçekleşmiştir?',options:['2','3','5','7'],answer:2,explanation:'Hendek Gazvesi genel kabulde hicretin beşinci yılıdır.',source:'Ahzâb Suresi; siyer kaynakları'),
  QuizQuestion(id:'s14',category:'Siyer',question:'Hudeybiye Antlaşması hangi hicrî yılda yapılmıştır?',options:['4','6','8','10'],answer:1,explanation:'Antlaşma hicretin altıncı yılında yapılmıştır.',source:'Fetih Suresi; Sahih al-Buhari, Şurût'),
  QuizQuestion(id:'s15',category:'Siyer',question:'Mekke’nin fethi hangi hicrî yılda gerçekleşmiştir?',options:['6','7','8','9'],answer:2,explanation:'Fetih hicretin sekizinci yılında gerçekleşmiştir.',source:'Siyer ve megāzî kaynakları'),
  QuizQuestion(id:'s16',category:'Siyer',question:'Veda Haccı hangi hicrî yılda yapılmıştır?',options:['8','9','10','11'],answer:2,explanation:'Hz. Muhammed hicretin onuncu yılında Veda Haccı yaptı.',source:'Sahih Muslim, Hac; siyer kaynakları'),
  QuizQuestion(id:'s17',category:'Siyer',question:'Hz. Muhammed’in Medine’de yaptırdığı mescidin adı nedir?',options:['Mescid-i Nebevî','Mescid-i Haram','Kuba dışında Mescid-i Aksâ','Kıbleteyn'],answer:0,explanation:'Medine’deki mescit Mescid-i Nebevî olarak bilinir.',source:'Siyer kaynakları'),
  QuizQuestion(id:'s18',category:'Siyer',question:'Hz. Muhammed’in sütannesinin adı geleneksel siyer kaynaklarında nasıl geçer?',options:['Halime es-Sa‘diyye','Ümmü Seleme','Esma bint Ebî Bekir','Safiyye'],answer:0,explanation:'Çocukluk döneminde Halime es-Sa‘diyye’nin yanında kaldığı aktarılır.',source:'İbn Hişâm, es-Sîre'),
  QuizQuestion(id:'s19',category:'Siyer',question:'Hz. Muhammed’in dedesinin adı nedir?',options:['Ebû Tâlib','Abdülmuttalib','Abdullah','Hâşim'],answer:1,explanation:'Dedesi Abdülmuttalib’dir.',source:'İbn Hişâm, es-Sîre'),
  QuizQuestion(id:'s20',category:'Siyer',question:'Hz. Muhammed’in babasının adı nedir?',options:['Abdullah','Ebû Tâlib','Abdülmuttalib','Hâşim'],answer:0,explanation:'Babası Abdullah, annesi Âmine’dir.',source:'İbn Hişâm, es-Sîre'),
  QuizQuestion(id:'s21',category:'Siyer',question:'Hz. Muhammed’in annesinin adı nedir?',options:['Âmine','Halime','Hatice','Fâtıma'],answer:0,explanation:'Annesi Âmine bint Vehb’dir.',source:'İbn Hişâm, es-Sîre'),
  QuizQuestion(id:'s22',category:'Siyer',question:'İlk Müslümanlardan olup Habeşistan’a hicret eden topluluğun sığındığı hükümdar hangi unvanla anılır?',options:['Kisrâ','Necâşî','Kayser','Mukavkıs'],answer:1,explanation:'Habeşistan hükümdarı Necâşî unvanıyla anılır.',source:'İbn Hişâm, es-Sîre; Habeşistan hicreti bölümü'),
  QuizQuestion(id:'s23',category:'Siyer',question:'Mekke döneminde Müslümanların boykot nedeniyle çekildiği mahalle hangi adla bilinir?',options:['Şi‘b-i Ebî Tâlib','Kuba','Arafat','Hudeybiye'],answer:0,explanation:'Boykot yıllarında Şi‘b-i Ebî Tâlib’de sıkıntı yaşandı.',source:'İbn Hişâm, es-Sîre'),
  QuizQuestion(id:'s24',category:'Siyer',question:'Hz. Muhammed’in son haccı hangi adla anılır?',options:['Haccetü’l-İslâm','Veda Haccı','Kıran Haccı','Umretü’l-kazâ'],answer:1,explanation:'Hicretin onuncu yılındaki haccı Veda Haccı olarak bilinir.',source:'Sahih Muslim, Hac; siyer kaynakları'),
  QuizQuestion(id:'s25',category:'Siyer',question:'Hz. Muhammed’in vefat ettiği şehir hangisidir?',options:['Mekke','Medine','Taif','Kudüs'],answer:1,explanation:'Medine’de vefat etmiş ve Hz. Âişe’nin odasına defnedilmiştir.',source:'Sahih al-Buhari, Cenâiz; siyer kaynakları'),

  // 20 Islamic history questions
  QuizQuestion(id:'i01',category:'İslam Tarihi',question:'Hicrî takvimin başlangıcı hangi olaya dayandırılır?',options:['Bedir Savaşı','Hicret','Mekke’nin fethi','Veda Haccı'],answer:1,explanation:'Hicrî takvim, Hz. Muhammed’in Mekke’den Medine’ye hicretini başlangıç kabul eder.',source:'İslam tarihi; Hz. Ömer dönemi takvim düzenlemesi'),
  QuizQuestion(id:'i02',category:'İslam Tarihi',question:'Dört Halife döneminin ilk halifesi kimdir?',options:['Hz. Ömer','Hz. Osman','Hz. Ebû Bekir','Hz. Ali'],answer:2,explanation:'Hz. Ebû Bekir ilk halifedir.',source:'Erken İslam tarihi kaynakları'),
  QuizQuestion(id:'i03',category:'İslam Tarihi',question:'Dört Halife döneminin ikinci halifesi kimdir?',options:['Hz. Ali','Hz. Ömer','Hz. Osman','Hz. Ebû Bekir'],answer:1,explanation:'Hz. Ömer, Hz. Ebû Bekir’den sonra halife olmuştur.',source:'Erken İslam tarihi kaynakları'),
  QuizQuestion(id:'i04',category:'İslam Tarihi',question:'Kur’an nüshalarının çoğaltılarak önemli merkezlere gönderilmesi hangi halife döneminde yapılmıştır?',options:['Hz. Ebû Bekir','Hz. Ömer','Hz. Osman','Hz. Ali'],answer:2,explanation:'Standart mushaf nüshalarının çoğaltılması Hz. Osman döneminde gerçekleşti.',source:'Sahih al-Buhari, Fedâilü’l-Kur’an'),
  QuizQuestion(id:'i05',category:'İslam Tarihi',question:'Emevî Devleti’nin başkenti hangi şehirdi?',options:['Bağdat','Şam','Kahire','Kûfe'],answer:1,explanation:'Emevî yönetiminin merkezi Şam’dı.',source:'İslam tarihi kaynakları'),
  QuizQuestion(id:'i06',category:'İslam Tarihi',question:'Abbâsî Devleti’nin 762 yılında kurulan başkenti hangisidir?',options:['Şam','Bağdat','Kahire','Kurtuba'],answer:1,explanation:'Bağdat, Abbâsî halifesi Mansûr tarafından başkent yapıldı.',source:'İslam tarihi kaynakları; Bağdat’ın kuruluşu'),
  QuizQuestion(id:'i07',category:'İslam Tarihi',question:'Endülüs’te Müslümanların kurduğu önemli merkez şehir hangisidir?',options:['Kurtuba','Semerkant','Buhara','Basra'],answer:0,explanation:'Kurtuba, Endülüs Emevîleri döneminde önemli bir merkezdi.',source:'Endülüs tarihi kaynakları'),
  QuizQuestion(id:'i08',category:'İslam Tarihi',question:'İslam tarihinde “Beytülhikme” özellikle hangi şehirle ilişkilidir?',options:['Bağdat','Mekke','Medine','İstanbul'],answer:0,explanation:'Beytülhikme, Abbâsî Bağdat’ında ilim ve tercüme faaliyetleriyle anılır.',source:'Abbâsî dönemi bilim tarihi'),
  QuizQuestion(id:'i09',category:'İslam Tarihi',question:'Malazgirt Savaşı hangi yıl yapılmıştır?',options:['751','1071','1099','1453'],answer:1,explanation:'Malazgirt Savaşı 1071 yılında gerçekleşti.',source:'Selçuklu ve Bizans tarihi kaynakları'),
  QuizQuestion(id:'i10',category:'İslam Tarihi',question:'Kudüs’ün Haçlılardan geri alınmasında öne çıkan Müslüman hükümdar kimdir?',options:['Selahaddin Eyyûbî','Alparslan','Fatih Sultan Mehmet','Harun Reşid'],answer:0,explanation:'Selahaddin Eyyûbî 1187’de Kudüs’ü geri aldı.',source:'Orta Çağ İslam tarihi kaynakları'),
  QuizQuestion(id:'i11',category:'İslam Tarihi',question:'Osmanlı Devleti’nin kurucusu kim kabul edilir?',options:['Orhan Gazi','Osman Gazi','I. Murad','Yıldırım Bayezid'],answer:1,explanation:'Osman Gazi, Osmanlı Beyliği’nin kurucusu kabul edilir.',source:'Osmanlı kronikleri ve tarih araştırmaları'),
  QuizQuestion(id:'i12',category:'İslam Tarihi',question:'İstanbul hangi yıl Osmanlı tarafından fethedilmiştir?',options:['1299','1402','1453','1517'],answer:2,explanation:'İstanbul 29 Mayıs 1453’te fethedildi.',source:'Osmanlı tarihi kaynakları'),
  QuizQuestion(id:'i13',category:'İslam Tarihi',question:'İstanbul’un fethi sırasında Osmanlı padişahı kimdi?',options:['II. Murad','Fatih Sultan Mehmet','Yavuz Sultan Selim','Kanuni Sultan Süleyman'],answer:1,explanation:'Fetih, II. Mehmed döneminde gerçekleşti.',source:'Osmanlı tarihi kaynakları'),
  QuizQuestion(id:'i14',category:'İslam Tarihi',question:'Osmanlı’da halifelik unvanı hangi padişah döneminde Osmanlı hanedanıyla ilişkilendirilmiştir?',options:['Yavuz Sultan Selim','Osman Gazi','Orhan Gazi','III. Selim'],answer:0,explanation:'1517 Mısır seferi sonrasında halifelikle ilgili tarihsel anlatı Yavuz Sultan Selim’le ilişkilendirilir; unvanın devri konusunda tarihçiler arasında tartışmalar vardır.',source:'Osmanlı-Memlük tarihi; modern tarihçilikte tartışmalı konu'),
  QuizQuestion(id:'i15',category:'İslam Tarihi',question:'İslam medeniyetinde cebir alanındaki çalışmalarıyla tanınan bilgin kimdir?',options:['Hârizmî','İbn Battûta','Farabî','İbn Haldun'],answer:0,explanation:'Muhammed bin Mûsâ el-Hârizmî cebir tarihinin öncü isimlerindendir.',source:'Bilim tarihi kaynakları'),
  QuizQuestion(id:'i16',category:'İslam Tarihi',question:'“El-Kanun fi’t-Tıbb” adlı eser hangi bilginle ilişkilidir?',options:['İbn Sînâ','Râzî','İbn Rüşd','Birûnî'],answer:0,explanation:'El-Kanun fi’t-Tıbb İbn Sînâ’nın tıp eseridir.',source:'İslam bilim tarihi kaynakları'),
  QuizQuestion(id:'i17',category:'İslam Tarihi',question:'Seyahatnamesiyle tanınan 14. yüzyıl gezgini kimdir?',options:['İbn Battûta','Hârizmî','Gazâlî','İbn Sînâ'],answer:0,explanation:'İbn Battûta geniş coğrafyalara yaptığı seyahatlerle tanınır.',source:'İbn Battûta, er-Rihle'),
  QuizQuestion(id:'i18',category:'İslam Tarihi',question:'Mukaddime adlı eser hangi düşünürün eseridir?',options:['İbn Haldun','Farabî','İbn Rüşd','Taberî'],answer:0,explanation:'Mukaddime, İbn Haldun’un tarih ve toplum düşüncesiyle tanınan eseridir.',source:'İbn Haldun, el-Mukaddime'),
  QuizQuestion(id:'i19',category:'İslam Tarihi',question:'Müslümanların İspanya’ya geçişinde adı öne çıkan komutan kimdir?',options:['Tarık bin Ziyad','Halid bin Velid','Amr bin Âs','Kâsım es-Sekafî'],answer:0,explanation:'711’deki Endülüs geçişi Tarık bin Ziyad ile anılır.',source:'Endülüs tarihi kaynakları'),
  QuizQuestion(id:'i20',category:'İslam Tarihi',question:'Osmanlı Devleti’nde Tanzimat Fermanı hangi yıl ilan edilmiştir?',options:['1789','1839','1876','1908'],answer:1,explanation:'Tanzimat Fermanı 3 Kasım 1839’da ilan edildi.',source:'Osmanlı modernleşme tarihi kaynakları'),
];
